                take = min(work[i], fifo_left)
                work[i] = work[i] - take
                fifo_left = fifo_left - take
            lifo_left = scale_l * (1.0 - f) * mu
            for k in range(m):
                i = m - 1 - k
                take = min(work[i], lifo_left)
                work[i] = work[i] - take
                lifo_left = lifo_left - take
            nxt = [0.0] * m
